var CONV_T = window.CONV_T || {}; CONV_T["de"] = {"udca":["Umgekehrte Signale (norwegisch: niedrige Karte ermutigt)","Auf das Ausspiel des Partners ermutigt eine niedrige Karte (Farbe fortsetzen), eine hohe entmutigt — umgekehrt zum Standard. Die Längenmarke bleibt Standard: hoch-niedrig zeigt eine gerade Anzahl."],"claudex":["Claude-Kontra","Claude-System (Bridge Table). Im Teilkontraktkampf ist das Kontra eines gegnerischen Farbkontrakts auf Zweier- oder Dreierstufe ein Strafkontra, wenn der Kontrierende mindestens zwei Faller zählt: seine Trumpfstiche und schnellen Stiche außen, plus den Anteil des Partners (ein Stich je vier gezeigte Punkte), gegen die 7 − Stufe Stiche, die sie abgeben dürfen. Es braucht drei oder mehr Trümpfe. Der Partner passt, außer mit Chicane in ihrer Farbe und eigener langer Farbe."],"twoOverOne":["2/1 Partieforcing","Aus nicht gepasster Hand ist eine neue Farbe auf Zweierstufe nach Partners Eröffnung auf Einerstufe (außer 1♣–2♦; 1♠–2♥ zeigt fünf Coeur) partieforcierend, 12+ FP. Über 1♥/1♠ ist 1SA für eine Runde forcierend (6-12 FP): der Eröffner reizt mangels anderer Wahl eine Dreierfarbe in Unterfarbe; der spätere Sprung des Antwortenden auf 3 in der Oberfarbe zeigt eine Limit-Hebung mit drei Karten. Eine Zweierantwort aus gepasster Hand ist nicht forcierend."],"rkc":["RKCB 1430","4SA fragt nach fünf Schlüsselkarten (vier Asse + Trumpfkönig). 5♣ = 1 oder 4, 5♦ = 3 oder 0, 5♥ = 2 ohne Trumpfdame, 5♠ = 2 mit Trumpfdame."],"rkc0314":["RKCB 0314","4SA fragt nach fünf Schlüsselkarten (vier Asse + Trumpfkönig). 5♣ = 0 oder 3, 5♦ = 1 oder 4, 5♥ = 2 ohne Trumpfdame, 5♠ = 2 mit Trumpfdame. Ersetzt RKCB 1430."],"gerber":["Gerber","Über 1SA, 2SA oder 3SA des Partners, ohne vereinbarte Farbe, fragt 4♣ nach Assen. 4♦ = 0 oder 4, 4♥ = 1, 4♠ = 2, 4SA = 3. Der Fragende kann in 4SA stoppen."],"bergen":["Bergen-Hebungen","Über 1♥/1♠ (nicht nach Kontra oder Gegenreizung): 3♣ = Vierer-Unterstützung, 7-9 Punkte; 3♦ = Vierer-Unterstützung, 10-12 (Limit-Hebung); 3 in der Oberfarbe = Vierer-Unterstützung, 0-6 (präemptiv). Mit vier Karten und 13+ nimmt man Jacoby 2SA oder einen Splinter. Die einfache Hebung zeigt drei Karten, 6-9; eine Limit-Hebung mit drei Karten geht über das forcierende 1SA."],"capp":["Cappelletti","Über das gegnerische 1SA (direkt): X = Strafe, 15+ FP. 2♣ = Einfärber (6+ Karten): Partner fragt mit 2♦, der Gegenreizer passt mit Karo oder nennt die Farbe. 2♦ = beide Oberfarben (5-4 oder länger): Partner wählt eine Oberfarbe (ein Sprung ist einladend, 10-12). 2♥/2♠ = 5+ in dieser Oberfarbe und eine 4+ Unterfarbe: Partner passt, hebt oder fragt mit 2SA nach der Unterfarbe. 2SA = beide Unterfarben (5-5): Partner wählt."],"j2nt":["Jacoby 2SA","2SA über eine Oberfarberöffnung = 4+ Unterstützung, 13+ Punkte, partieforcierend. Eröffner: 3 in neuer Farbe = Single oder Chicane; 4 in neuer Farbe = gute Fünfer-Nebenfarbe; 3 in der Oberfarbe = 18+ ohne Kürze; 3SA = 15-17 ohne Kürze; 4 in der Oberfarbe = Minimum."],"wjs":["Schwache Sprungwechsel","Ein einfacher Sprung des Antwortenden in einer neuen Farbe (z. B. 1♦–2♠, 1♣–2♥) zeigt 6+ Karten und eine schwache Hand (0-5 FP). Zum Spielen; der Eröffner passt. Nicht nach gegnerischem Kontra."],"stayman":["Stayman","2♣ über 1SA (3♣ über 2SA) fragt nach einer Vierer-Oberfarbe. Antworten: ♦ = keine Vierer-Oberfarbe, ♥ = vier Coeur, ♠ = vier Pik und nicht vier Coeur. Nach 2♦ zeigen 2♥/2♠ fünf in dieser Oberfarbe + vier in der anderen, einladend. Reizt der Antwortende SA über 2♥, nennt der Eröffner mit vier Pik diese auch."],"minorTr":["Unterfarb-Transfer","Nach 1SA: 2♠ → Treff (Eröffner reizt 3♣), 3♣ → Karo (Eröffner reizt 3♦). Eine schwache Hand mit sechster Unterfarbe spielt auf drei; 2SA bleibt eine natürliche Einladung."],"fourWay":["Vierfach-Transfers","Über 1SA: 2♦ → Coeur, 2♥ → Pik (Jacoby), 2♠ → Treff (Eröffner reizt 3♣), 2SA → Karo (Eröffner reizt 3♦). Ausgeglichene Einladungen gehen über 2♣ Stayman."],"puppet":["Puppet Stayman","Nach 2SA fragt 3♣ nach einer Vierer- oder Fünfer-Oberfarbe (statt Stayman). Antworten: 3♦ = eine oder zwei Vierer-Oberfarben, 3♥ = fünf Coeur, 3♠ = fünf Pik, 3SA = keine Vierer-Oberfarbe. Nach 3♦ reizt der Antwortende die Oberfarbe, die er nicht hat: 3♥ = vier Pik, 3♠ = vier Coeur, 4♦ = beide, 3SA = keine; so spielt der 2SA-Eröffner."],"smolen":["Smolen","Nach 1SA–2♣–2♦ reizt eine partieforcierende Hand mit 5-4 in Oberfarben ihre Vierer-Oberfarbe auf Dreierstufe: 3♥ = 4♥ + 5♠, 3♠ = 4♠ + 5♥, damit die starke Hand spielt."],"michaels":["Michaels-Cuebid / Unusual 2SA","Ein direktes Cuebid ihrer Einer-Eröffnung zeigt einen 5-5-Zweifärber, 7+ FP: über Unterfarbe beide Oberfarben; über Oberfarbe die andere Oberfarbe und eine Unterfarbe (Partner fragt mit 2SA nach der Unterfarbe). Ein Sprung auf 2SA (Unusual) zeigt die zwei niedrigsten ungereizten Farben. Partner wählt; mit Fit und 10+ kann er in die Partie springen."],"splinter":["Splinter","Doppelsprung in neuer Farbe über eine Oberfarberöffnung (z. B. 1♠–4♥, 1♥–3♠) = 4+ Unterstützung, Single oder Chicane in der genannten Farbe, 11-15 FP, partieforcierend, Schleminteresse. Der Eröffner stoppt in 4 der Oberfarbe oder erkundet den Schlemm."],"texas":["Texas-Transfers","Über 1SA/2SA: 4♦ → 4♥, 4♥ → 4♠. 6+ Oberfarbe mit Partiewerten; die starke Hand (Eröffner) spielt."],"texasInt":["Texas nach Störung","Texas gilt weiter, wenn die Gegner unser 1SA kontrieren oder auf Zweier- oder Dreierstufe gegenreizen: 4♦ → Coeur, 4♥ → Pik. Ein Gebot in ihrer Farbe ist kein Transfer (nach 2♥-Gegenreizung ist 4♥ ein Cuebid und 4♦ zeigt weiter Coeur). Der Eröffner vervollständigt den Transfer."],"leb":["Lebensohl","Nach Gegenreizung auf Zweierstufe über unser 1SA: 2SA zwingt den Eröffner zu 3♣ (um in einer Farbe zu stoppen oder langsam zu zeigen). Eine direkte Farbe auf Dreierstufe ist forcierend. Direktes 3SA verneint einen Stopper; erst 2SA, dann 3SA zeigt einen. Ein Cuebid ihrer Farbe ist Stayman: direkt = ohne Stopper, über 2SA = mit Stopper („fast denies“)."],"lav":["Lavinthal-Abwürfe","Markierung in der Verteidigung. Die abgeworfene Farbe ist unerwünscht; eine hohe Karte fragt nach der höheren der beiden anderen Farben, eine niedrige nach der niedrigeren (Trumpf und ausgespielte Farbe zählen nicht). Auf Partners Ausspiel ermutigt eine hohe Karte, die niedrigste entmutigt."],"roman":["Römische Abwürfe (gerade-ungerade)","Markierung in der Verteidigung. Erster Abwurf: eine ungerade Karte (3, 5, 7, 9) wünscht die Farbe; eine gerade (2, 4, 6, 8, 10) will sie nicht und wünscht eine der beiden anderen Farben: eine niedrige gerade (2, 4) die niedrigere, eine hohe (6, 8, 10) die höhere (Trumpf und gespielte Farbe zählen nicht). Auf Partners Ausspiel ermutigt eine hohe kleine Karte, die niedrigste lehnt ab."],"invMin":["Inverted Minors","Aus nicht gepasster Hand über 1♣/1♦: die Hebung auf 2 der Unterfarbe ist stark (10+ Punkte, 4+ Unterstützung, 5+ in Treff, keine Vierer-Oberfarbe) und eine Runde forcierend; der Eröffner reizt mit ausgeglichenem Minimum 2SA, zeigt mit Extras Stopper oder wiederholt mit Minimum 3 der Unterfarbe. Die Sprunghebung auf 3 ist präemptiv (0-9 Punkte, 5+ Unterstützung)."],"drury":["Drury","Reverse Drury. Eine gepasste Hand antwortet auf Partners 1♥/1♠ in dritter/vierter Hand mit 2♣ = 3+ Unterstützung und 10-12 Punkte. Der Eröffner reizt mit leichter oder minimaler Eröffnung 2 in der Oberfarbe (keine Partie) und mit voller Eröffnung 4."],"nmf":["New Minor Forcing","Nach 1m–1M–1SA ist 2 in der anderen Unterfarbe des Antwortenden künstlich und forcierend (11+): es fragt den Eröffner nach Dreier-Unterstützung in der Oberfarbe des Antwortenden oder der anderen Vierer-Oberfarbe."],"fsf":["Vierte Farbe forcierend","Haben wir drei Farben gereizt, ist das Gebot des Antwortenden in der vierten Farbe künstlich und partieforcierend; es bittet den Eröffner, seine Hand weiter zu beschreiben (Stopper, Unterstützung oder Zusatzlänge)."],"ogust":["Ogust","Über Partners Weak Two fragt 2SA: 3♣ = Minimum, schlechte Farbe; 3♦ = Minimum, gute Farbe; 3♥ = Maximum, schlechte Farbe; 3♠ = Maximum, gute Farbe; 3SA = feste Farbe (AKD)."],"supx":["Support-Kontra","Nach 1m–(P)–1M–(Gegenreizung unter 2M) zeigt das Kontra des Eröffners genau drei Karten Unterstützung für die Oberfarbe des Antwortenden; die direkte Hebung zeigt vier."],"respx":["Responsive Kontra","Nach ihrer Eröffnung, Partners Informationskontra und ihrer Hebung ist ein Kontra des Partners informativ: 8+ Punkte und beide ungereizten Farben (meist die Oberfarben), ohne klares Gebot."],"sjs":["Starke Sprungwechsel","Ein einfacher Sprung des Antwortenden in neuer Farbe zeigt eine starke Hand (19+ Punkte) mit guter Farbe und Schleminteresse. Ersetzt die schwachen Sprungwechsel."],"dont":["DONT","Disturb Opponents’ Notrump (Marty Bergen). Über ihr 1SA: X = Einfärber (6+), Partner fragt mit 2♣; 2♣ = Treff und eine höhere Farbe; 2♦ = Karo und eine Oberfarbe; 2♥ = beide Oberfarben; 2♠ = nur Pik (natürlich). Partner passt mit Toleranz oder reizt die nächste Farbe (pass or correct). Ersetzt Cappelletti."],"jtr":["Jacoby-Transfer","Über 1SA bittet 2♦ den Eröffner, Coeur zu reizen, und 2♥, Pik zu reizen, damit die starke Hand spielt. Mit vier Karten Unterstützung und Maximum (17) superakzeptiert der Eröffner auf Dreierstufe. Nach dem Transfer ist eine neue Farbe auf Dreierstufe natürlich und partieforcierend."],"sys":["Systemgebot","Ein künstliches Gebot des gewählten Systems (Precision, Polnisch Treff, Multi 2♦): was es zeigt, steht oben. Das System wählst du auf der Startseite (Dein System) oder in den Einstellungen."],"bw":["Blackwood","4SA fragt nach Assen: 5♣ = 0 oder 4, 5♦ = 1, 5♥ = 2, 5♠ = 3."],"q":["Quantitatives 4SA","Nach einem Sans-Atout-Gebot fragt 4SA nicht nach Assen; es lädt zum Schlemm ein. Partner reizt mit Maximum 6SA."],"nego":["Negatives Kontra","Hat Partner eröffnet und der Gegner gegengereizt, ist Kontra kein Strafkontra: es zeigt vier Karten in der ungereizten Oberfarbe und genug Werte zum Reizen."],"takeout":["Informationskontra","Kontra einer Eröffnung: Eröffnungswerte, Kürze in ihrer Farbe und Unterstützung in den anderen Farben. Partner muss reizen."],"weak2":["Weak Two","Eröffnung 2♦/2♥/2♠: gute Sechserfarbe, 5-10 FP. Eine präemptive Eröffnung."],"strong2c":["Starkes 2♣","Eröffnung 2♣: 22+ FP oder gleichwertige Spielstärke, künstlich und partieforcierend. 2♦ ist die Warteantwort. Nach 2♣–2♦–2♥/2♠ ist 3♣ das zweite Negativ (0-3 FP); 2♣–2♦–2SA (22-24) wird wie eine 2SA-Eröffnung gereizt (Stayman und Transfers)."],"cue":["Cuebid","Die Farbe der Gegner zu reizen ist nicht natürlich: es zeigt Unterstützung für Partner mit Limit-Hebung oder mehr und ist forcierend."],"nt1":["1SA-Eröffnung","15-17 FP, ausgeglichen."],"pre":["Sperrgebot","Eröffnung auf Dreier- oder Viererstufe: lange Farbe (7+) und schwache Hand, nimmt den Gegnern Reizraum."],"runout":["Flucht nach kontriertem 1SA","Wird unser 1SA kontriert, flüchtet ein schwacher Antwortender in eine 5+ Farbe; Rekontra zeigt Werte (9+)."]};
var SYS_T = window.SYS_T || {}; SYS_T["de"] = {"claude":"Das Claude-System, gemacht von Claude (der KI von Anthropic) für Bridge Table: eine natürliche Basis — Fünfer-Oberfarben, bessere Unterfarbe 1♣/1♦, 1SA 15-17, starkes 2♣ und künstliches partieforcierendes 2♦, schwache 2♥/2♠ — mit eigenen Konventionen, gemessen über Tausende von Boards double dummy: das Claude-Kontra.","twoone":"Fünfer-Oberfarben, 1SA 15-17, Weak Twos, starkes 2♣. Eine neue Farbe auf Zweierstufe aus nicht gepasster Hand ist partieforcierend; 1SA über eine Oberfarbe ist forcierend.","sayc":"Fünfer-Oberfarben, 1SA 15-17, Weak Twos, starkes 2♣, Jacoby-Transfers und Stayman, Blackwood. Eine neue Farbe auf Zweierstufe ist eine Runde forcierend (10+); 1SA über eine Oberfarbe ist 6-10 und nicht forcierend; Sprungwechsel sind stark.","acol":"Vierer-Oberfarben, schwaches 1SA (12-14), starkes 2♣ (23+ oder Partieforcing), Weak Twos in ♦ ♥ ♠, Limit-Hebungen (eine Hebung verspricht vier Karten), 2SA 20-22, Stayman und Transfers, RKCB.","sef":"Système d’Enseignement Français: Fünfer-Oberfarben, „beste Unterfarbe“ 1♣/1♦, 1SA 15-17, 2♣ stark und forcierend, 2♦ künstlich partieforcierend, schwache 2♥/2♠. Eine neue Farbe auf Zweierstufe ist eine Runde forcierend; RKCB.","precision":"Starkes Treff: 1♣ = 16+ beliebige Verteilung (künstlich, forcierend; 1♦ = negativ 0-7). Andere Eröffnungen 11-15: 1♦ 2+ ♦ (Sammelgebot), 1♥/1♠ 5+, 1SA 13-15, 2♣ 6+ ♣ (oder 5♣ + Vierer-Oberfarbe), 2♦ Dreifärber kurz in ♦ (4-4-1-4 / 4-4-0-5), schwache 2♥/2♠.","polish":"Wspólny Język: 1♣ = (a) 12-14 ausgeglichen, (b) 15+ mit langen Treff oder (c) 18+ beliebig (1♦ = negativ 0-7 oder Warteantwort). 1♦ 4+ ♦ unausgeglichen, 1♥/1♠ 5+, 1SA 15-17, 2♣ 6+ ♣ 11-15, 2♦ Multi (Weak Two in ♥ oder ♠), schwache 2♥/2♠."};
